import { NODIR, IMMEDIATE } from './const.js';
// o_init.js — object initialisation and description shuffling.
// C ref: src/o_init.c
//
// This is the first thing in the game that draws a random number: every
// recorded session's very first PRNG call is
// `rn2(2) @ randomize_gem_colors(o_init.c:89)`. Nothing later in the stream can
// align until this file does.
//
// The object tables come from js/objects_data.js, generated by
// tools/gen-objects.mjs.

import { game } from './gstate.js';
import { PMNAMES } from './monst_data.js';
import { exercise } from './attrib.js';
import { A_WIS } from './const.js';
import { rn2 } from './rng.js';
import { obj_typename, OBJ_DESCR as objDescrOf, OBJ_NAME,
         Japanese_item_name } from './objnam.js';
import { ATR_NONE, ATR_INVERSE } from './tty/wintty.js';
import {
    objects as OBJECTS_INIT, obj_descr as OBJ_DESCR_INIT,
    NUM_OBJECTS, ONAMES, OCLASSES,
} from './objects_data.js';

const {
    ARMOR_CLASS, RING_CLASS, AMULET_CLASS,
    POTION_CLASS, SCROLL_CLASS, SPBOOK_CLASS, WAND_CLASS, GEM_CLASS,
    VENOM_CLASS, MAXOCLASSES,
} = OCLASSES;

const {
    HELMET, HELM_OF_TELEPATHY, LEATHER_GLOVES, GAUNTLETS_OF_DEXTERITY,
    CLOAK_OF_PROTECTION, CLOAK_OF_DISPLACEMENT, SPEED_BOOTS, LEVITATION_BOOTS,
    POT_WATER, WAN_NOTHING, LAST_REAL_GEM,
} = ONAMES;

// include/objclass.h — oc_dir values.
/* NODIR and IMMEDIATE live in js/const.js with the oc_dir family. */

// The generated table stores oc_class as the C identifier ("WEAPON_CLASS");
// resolve to the numeric class once so the hot paths compare ints as C does.
function numericClass(v) {
    return typeof v === 'string' ? OCLASSES[v] : v;
}

// A fresh, mutable copy of objects[]. shuffle() swaps fields between entries,
// so this is per-game state, never the shared generated table.
export function reset_objects() {
    game.objects = OBJECTS_INIT.map(o => ({ ...o, oc_class: numericClass(o.oc_class) }));
    game.obj_descr = OBJ_DESCR_INIT.map(d => ({ ...d }));
    game.bases = new Array(MAXOCLASSES + 2).fill(0);
    game.oclass_prob_totals = new Array(MAXOCLASSES).fill(0);
    return game.objects;
}

// OBJ_DESCR(obj) from include/objclass.h
function OBJ_DESCR(i) { return game.obj_descr[i].oc_descr; }

// src/o_init.c:54 setgemprobs()
// init_objects() calls this with dlev == 0, so lev is 0 there.
export function setgemprobs(dlev) {
    const objects = game.objects;
    let j, first, lev, sum = 0;

    if (dlev) lev = dlev.ledger_no > dlev.maxledgerno ? dlev.maxledgerno : dlev.ledger_no;
    else lev = 0;
    first = game.bases[GEM_CLASS];

    for (j = 0; j < 9 - Math.trunc(lev / 3); j++)
        objects[first + j].oc_prob = 0;
    first += j;

    for (j = first; j <= LAST_REAL_GEM; j++)
        objects[j].oc_prob = Math.trunc((171 + j - first) / (LAST_REAL_GEM + 1 - first));

    /* recompute GEM_CLASS total oc_prob - including rocks/stones */
    for (j = game.bases[GEM_CLASS]; j < game.bases[GEM_CLASS + 1]; j++)
        sum += objects[j].oc_prob;
    game.oclass_prob_totals[GEM_CLASS] = sum;
}

// src/o_init.c:85 randomize_gem_colors()
// Three draws, and they are the first three of every game.
export function randomize_gem_colors() {
    const objects = game.objects;
    const { TURQUOISE, SAPPHIRE, AQUAMARINE, FLUORITE, DIAMOND, EMERALD } = ONAMES;
    const COPY_OBJ_DESCR = (o_dst, o_src) => {
        objects[o_dst].oc_descr_idx = objects[o_src].oc_descr_idx;
        objects[o_dst].oc_color = objects[o_src].oc_color;
    };

    if (rn2(2)) { /* change turquoise from green to blue? */
        COPY_OBJ_DESCR(TURQUOISE, SAPPHIRE);
    }
    if (rn2(2)) { /* change aquamarine from green to blue? */
        COPY_OBJ_DESCR(AQUAMARINE, SAPPHIRE);
    }
    switch (rn2(4)) { /* change fluorite from violet? */
    case 0:
        break;
    case 1: /* blue */
        COPY_OBJ_DESCR(FLUORITE, SAPPHIRE);
        break;
    case 2: /* white */
        COPY_OBJ_DESCR(FLUORITE, DIAMOND);
        break;
    case 3: /* green */
        COPY_OBJ_DESCR(FLUORITE, EMERALD);
        break;
    }
}

// src/o_init.c:113 shuffle() — shuffle descriptions on objects o_low to o_high.
// This is the bulk of the corpus's o_init draws (10,725 of them). The rejection
// loop matters: every rejected candidate consumes another rn2.
function shuffle(o_low, o_high, domaterial) {
    const objects = game.objects;
    let i, j, num_to_shuffle;
    let sw, color;

    for (num_to_shuffle = 0, j = o_low; j <= o_high; j++)
        if (!objects[j].oc_name_known)
            num_to_shuffle++;
    if (num_to_shuffle < 2)
        return;

    for (j = o_low; j <= o_high; j++) {
        if (objects[j].oc_name_known)
            continue;
        do
            i = j + rn2(o_high - j + 1);
        while (objects[i].oc_name_known);
        sw = objects[j].oc_descr_idx;
        objects[j].oc_descr_idx = objects[i].oc_descr_idx;
        objects[i].oc_descr_idx = sw;
        sw = objects[j].oc_tough;
        objects[j].oc_tough = objects[i].oc_tough;
        objects[i].oc_tough = sw;
        color = objects[j].oc_color;
        objects[j].oc_color = objects[i].oc_color;
        objects[i].oc_color = color;

        /* shuffle material */
        if (domaterial) {
            sw = objects[j].oc_material;
            objects[j].oc_material = objects[i].oc_material;
            objects[i].oc_material = sw;
        }
    }
}

// src/o_init.c:240 init_oclass_probs()
export function init_oclass_probs() {
    const objects = game.objects;
    let i, sum, oclass;

    for (oclass = 0; oclass < MAXOCLASSES; ++oclass) {
        sum = 0;
        /* note: for ILLOBJ_CLASS, bases[oclass+1]-1 isn't the last item
           in the class; but all the generic items have probability 0 so
           adding them to 'sum' has no impact */
        for (i = game.bases[oclass]; i < game.bases[oclass + 1]; ++i) {
            sum += objects[i].oc_prob;
        }
        game.oclass_prob_totals[oclass] = sum;
    }
}

// src/o_init.c:269 obj_shuffle_range() — the range otyp shares descriptions
// with. Returns { lo, hi } instead of writing through out-pointers.
export function obj_shuffle_range(otyp) {
    const objects = game.objects;
    let i;
    const ocls = objects[otyp].oc_class;

    /* default is just the object itself */
    let lo = otyp, hi = otyp;

    switch (ocls) {
    case ARMOR_CLASS:
        if (otyp >= HELMET && otyp <= HELM_OF_TELEPATHY)
            { lo = HELMET; hi = HELM_OF_TELEPATHY; }
        else if (otyp >= LEATHER_GLOVES && otyp <= GAUNTLETS_OF_DEXTERITY)
            { lo = LEATHER_GLOVES; hi = GAUNTLETS_OF_DEXTERITY; }
        else if (otyp >= CLOAK_OF_PROTECTION && otyp <= CLOAK_OF_DISPLACEMENT)
            { lo = CLOAK_OF_PROTECTION; hi = CLOAK_OF_DISPLACEMENT; }
        else if (otyp >= SPEED_BOOTS && otyp <= LEVITATION_BOOTS)
            { lo = SPEED_BOOTS; hi = LEVITATION_BOOTS; }
        break;
    case POTION_CLASS:
        /* potion of water has the only fixed description */
        lo = game.bases[POTION_CLASS];
        hi = POT_WATER - 1;
        break;
    case AMULET_CLASS:
    case SCROLL_CLASS:
    case SPBOOK_CLASS:
        /* exclude non-magic types and also unique ones */
        lo = game.bases[ocls];
        for (i = lo; objects[i].oc_class === ocls; i++)
            if (objects[i].oc_unique || !objects[i].oc_magic)
                break;
        hi = i - 1;
        break;
    case RING_CLASS:
    case WAND_CLASS:
    case VENOM_CLASS:
        /* entire class */
        lo = game.bases[ocls];
        hi = game.bases[ocls + 1] - 1;
        break;
    }

    /* artifact checking might ask about item which isn't part of any range
       but fell within the classes that do have ranges specified above */
    if (otyp < lo || otyp > hi) { lo = otyp; hi = otyp; }
    return { lo, hi };
}

// src/o_init.c:322 shuffle_all() — randomize object descriptions.
function shuffle_all() {
    /* entire classes; obj_shuffle_range() handles their exceptions */
    const shuffle_classes = [
        AMULET_CLASS, POTION_CLASS, RING_CLASS, SCROLL_CLASS,
        SPBOOK_CLASS, WAND_CLASS, VENOM_CLASS,
    ];
    /* sub-class type ranges (one item from each group) */
    const shuffle_types = [
        HELMET, LEATHER_GLOVES, CLOAK_OF_PROTECTION, SPEED_BOOTS,
    ];
    let idx;

    /* do whole classes (amulets, &c) */
    for (idx = 0; idx < shuffle_classes.length; idx++) {
        const { lo, hi } = obj_shuffle_range(game.bases[shuffle_classes[idx]]);
        shuffle(lo, hi, true);
    }
    /* do type ranges (helms, &c) */
    for (idx = 0; idx < shuffle_types.length; idx++) {
        const { lo, hi } = obj_shuffle_range(shuffle_types[idx]);
        shuffle(lo, hi, false);
    }
}

// src/o_init.c:151 init_objects()
export function init_objects() {
    reset_objects();
    const objects = game.objects;
    let i, first, last, prevoclass;
    let oclass;

    for (i = 0; i <= MAXOCLASSES; i++)
        game.bases[i] = 0;

    /* initialize object descriptions */
    for (i = 0; i < NUM_OBJECTS; i++)
        objects[i].oc_name_idx = objects[i].oc_descr_idx = i;

    /* init base; if probs given check that they add up to 1000,
       otherwise compute probs */
    first = MAXOCLASSES;
    prevoclass = -1;
    while (first < NUM_OBJECTS) {
        oclass = objects[first].oc_class;

        last = first + 1;
        while (last < NUM_OBJECTS && objects[last].oc_class === oclass)
            last++;
        game.bases[oclass] = first;

        if (oclass === GEM_CLASS) {
            setgemprobs(null);
            randomize_gem_colors();
        }
        first = last;
        prevoclass = oclass;
    }
    /* extra entry allows deriving the range of a class via
       bases[class] through bases[class+1]-1 for all classes */
    game.bases[MAXOCLASSES] = game.bases[MAXOCLASSES + 1] = NUM_OBJECTS;

    /* guarantee that there are no gaps in bases[] */
    for (last = MAXOCLASSES - 1; last >= 0; --last)
        if (!game.bases[last])
            game.bases[last] = game.bases[last + 1];

    /* check objects[].oc_name_known.
       The C repairs a mismatch silently when sanity_check is off, and the
       repair changes oc_name_known — which changes how many draws shuffle()
       makes. It has to be ported, not skipped. */
    for (i = MAXOCLASSES; i < NUM_OBJECTS; ++i) {
        const nmkn = objects[i].oc_name_known !== 0 ? 1 : 0;

        if (((OBJ_DESCR(i) ? 0 : 1) ^ nmkn) !== 0) {
            /* repair the mistake and keep going */
            objects[i].oc_name_known = nmkn ? 0 : 1;
        }
    }

    /* compute oclass_prob_totals */
    init_oclass_probs();

    /* shuffle descriptions */
    shuffle_all();

    objects[WAN_NOTHING].oc_dir = rn2(2) ? NODIR : IMMEDIATE;
}

// ---------------------------------------------------------------------------
// Discoveries
// ---------------------------------------------------------------------------

// src/o_init.c:599 — flags.discosort selects the order; 'o' is the default and
// the only one the corpus uses.
const disco_order_let = 'osca';
const disco_orders_descr = [
    'by order of discovery within each class',
    'sortloot order (by class with some sub-class groupings)',
    'alphabetical within each class',
    'alphabetical across all classes',
];

// src/o_init.c:520 discover_object()
//
// src/o_init.c:442 observe_object() — naming an object in view marks its
// type as encountered. xname() calls this on every use, which is how a
// starting kit ends up '  listed' rather than '* listed' in discoveries.
export function observe_object(obj) {
    const oindx = obj.otyp;
    if (oindx >= 1 && !game.u?.uprops?.HALLUC) {
        obj.dknown = 1;
        discover_object(oindx, false, true, false);
    }
}

// svd.disco[] is NOT a flat list: it is indexed by object class, filled from
// svb.bases[class] upward, so discoveries stay grouped by class in the order
// they were made. dodiscovered() walks it that way.
export function discover_object(oindx, mark_as_known, mark_as_encountered,
                                credit_hero) {
    const objects = game.objects;
    if (oindx < 1)                    /* FIRST_OBJECT */
        return;

    if ((!objects[oindx].oc_name_known && mark_as_known)
        || (!objects[oindx].oc_encountered && mark_as_encountered)
        /* src/o_init.c — a Samurai's Japanese-named items go on the
           discoveries list even when the type is pre-known (a knife has no
           appearance so ships name_known; "shito [knife]" still lists) */
        || ((game.urole?.mnum === 'PM_SAMURAI'
             || game.urole?.mnum === PMNAMES.PM_SAMURAI)
            && Japanese_item_name(oindx, null))) {
        const acls = objects[oindx].oc_class;
        game.disco ||= [];

        let dindx = game.bases[acls];
        for (; game.disco[dindx]; dindx++)
            if (game.disco[dindx] === oindx)
                break;
        game.disco[dindx] = oindx;

        if (mark_as_encountered)
            objects[oindx].oc_encountered = 1;
        if (!objects[oindx].oc_name_known && mark_as_known) {
            objects[oindx].oc_name_known = 1;
            /* src/o_init.c:478 — learning a NEW type exercises wisdom,
               one rn2(19); re-knowing draws nothing */
            if (credit_hero)
                exercise(A_WIS, true);
        }
    }
}

// src/o_init.c:660 interesting_to_discover()
function interesting_to_discover(i) {
    /* most players who don't speak Japanese manage to figure out what
       gunyoki, osaku, and so forth mean, but treat them as pre-discovered
       to be disclosed by '\' */
    if ((game.urole?.mnum === 'PM_SAMURAI'
         || game.urole?.mnum === PMNAMES.PM_SAMURAI)
        && Japanese_item_name(i, null))
        return true;

    const o = game.objects[i];
    return !!o.oc_uname
        || ((o.oc_name_known || o.oc_encountered) && objDescrOf(o) !== null);
}

// src/o_init.c:668 disco_typename() — augment obj_typename() with the
// English explanation of a Japanese item name: "shito [knife]", or spliced
// before " called"/" (" when those follow.
function disco_typename(otyp) {
    let result = obj_typename(otyp);

    if ((game.urole?.mnum === 'PM_SAMURAI'
         || game.urole?.mnum === PMNAMES.PM_SAMURAI)
        && Japanese_item_name(otyp, null)) {
        const actualn =
            ((otyp !== ONAMES.MAGIC_HARP && otyp !== ONAMES.WOODEN_HARP)
             || game.objects[otyp].oc_name_known)
            ? OBJ_NAME(game.objects[otyp]) : 'harp';
        if (!actualn) {
            ;
        } else if (result.includes(' called')) {
            result = result.replace(' called', ` [${actualn}] called`);
        } else if (result.includes(' (')) {
            result = result.replace(' (', ` [${actualn}] (`);
        } else {
            result += ` [${actualn}]`;
        }
    }
    return result;
}

// src/o_init.c:686 dodiscovered() — build the discoveries text.
//
// Returns the lines rather than pushing them into a window, so the caller
// decides which window type to use. The header uses flags.inv_order for the
// class sequence, and each class heading is let_to_name(oclass).
export function dodiscovered() {
    const objects = game.objects;
    const sortindx = Math.max(0, disco_order_let.indexOf(game.flags?.discosort || 'o'));
    const lines = [];

    /* src/o_init.c passes iflags.menu_headings.attr for the class headings,
       which defaults to ATR_INVERSE (src/options.c:7188). Lines carry
       [text, attr] so the window layer can render them. */
    lines.push(['Discoveries, ' + disco_orders_descr[sortindx], ATR_NONE]);
    lines.push(['', ATR_NONE]);

    let ct = 0;
    for (const oclass of inv_order()) {
        let prev_class = -1;
        for (let i = game.bases[oclass];
             i < objects.length && objects[i].oc_class === oclass; i++) {
            const dis = game.disco?.[i];
            if (dis && interesting_to_discover(dis)) {
                ct++;
                if (oclass !== prev_class) {
                    lines.push([let_to_name(oclass), ATR_INVERSE]);
                    prev_class = oclass;
                }
                lines.push([(objects[dis].oc_encountered ? '  ' : '* ')
                            + disco_typename(dis), ATR_NONE]);
            }
        }
    }
    return ct ? lines : null;
}

// src/decl.c flags.inv_order — the default packorder.
function inv_order() {
    const O = OCLASSES;
    return [O.COIN_CLASS, O.AMULET_CLASS, O.WEAPON_CLASS, O.ARMOR_CLASS,
            O.FOOD_CLASS, O.SCROLL_CLASS, O.SPBOOK_CLASS, O.POTION_CLASS,
            O.RING_CLASS, O.WAND_CLASS, O.TOOL_CLASS, O.GEM_CLASS,
            O.ROCK_CLASS, O.BALL_CLASS, O.CHAIN_CLASS, O.VENOM_CLASS];
}

// src/objnam.c let_to_name() — the plural class heading used in menus.
const CLASS_NAMES = {
    COIN_CLASS: 'Coins', AMULET_CLASS: 'Amulets', WEAPON_CLASS: 'Weapons',
    ARMOR_CLASS: 'Armor', FOOD_CLASS: 'Comestibles', SCROLL_CLASS: 'Scrolls',
    SPBOOK_CLASS: 'Spellbooks', POTION_CLASS: 'Potions', RING_CLASS: 'Rings',
    WAND_CLASS: 'Wands', TOOL_CLASS: 'Tools', GEM_CLASS: 'Gems/Stones',
    ROCK_CLASS: 'Boulders/Statues', BALL_CLASS: 'Iron balls',
    CHAIN_CLASS: 'Chains', VENOM_CLASS: 'Venoms',
};
function let_to_name(oclass) {
    for (const [k, v] of Object.entries(OCLASSES))
        if (v === oclass && CLASS_NAMES[k]) return CLASS_NAMES[k];
    return '';
}

// src/o_init.c makeknown() — fully discover an object type; the wisdom
// exercise only fires when the type was actually unknown.
export function makeknown(otyp) {
    discover_object(otyp, true, true, true);
}
